  border: 1px solid var(--secondary-color);
}

.radio-label {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 15px;
  border-radius: 20px;
  transition: background 0.3s ease;
}

.radio-label:hover {
