/* Progress Modal */
.progress-modal {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.6);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 1000;
  backdrop-filter: blur(5px);
}

.progress-modal-content {
  background: var(--card-bg);
  padding: 25px;
  border-radius: 15px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
  width: 450px;
  text-align: center;
  position: relative;
  overflow: hidden;
  border: 2px solid var(--secondary-color);
  animation: float 3s ease-in-out infinite;
}

.modal-title {
  color: var(--primary-color);
  font-size: 2rem;
  margin-bottom: 25px;
  text-transform: uppercase;
  letter-spacing: 3px;
  animation: pulseText 2s ease-in-out infinite;
}

.progress-bar-container {
  position: relative;
  width: 100%;
  height: 50px;
  margin: 25px 0;
  perspective: 1000px;
}

.progress-bar-bg {
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, var(--bg-color), rgba(255, 255, 255, 0.15));
  border-radius: 25px;
  overflow: hidden;
  border: 3px solid var(--secondary-color);
  box-shadow: inset 0 0 10px rgba(0, 0, 0, 0.2);
}

.progress-bar-fill {
  --progress: 0%;
  height: 100%;
  width: var(--progress);
  background: linear-gradient(45deg, var(--secondary-color), var(--accent-color), var(--secondary-color));
  background-size: 200% 200%;
  border-radius: 25px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: width 0.8s cubic-bezier(0.4, 0, 0.2, 1);
  position: relative;
  overflow: hidden;
  transform-style: preserve-3d;
  animation: rotateFlow 4s linear infinite, progressGlow 1.5s ease-in-out infinite;
}

.progress-bar-fill::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.4), transparent);
  animation: wave 2s linear infinite;
}

.progress-text {
  font-size: 1.4rem;
  font-weight: bold;
  color: var(--bg-color);
  z-index: 1;
  text-shadow: 2px 2px 6px rgba(0, 0, 0, 0.7);
  animation: bounce 1.5s ease-in-out infinite;
}

.progress-unit {
  font-size: 1rem;
  margin-left: 8px;
  color: var(--bg-color);
  animation: fadeInOut 2s ease-in-out infinite;
}

.progress-pulse {
  position: absolute;
  top: 0;
  left: var(--progress);
  width: 15px;
  height: 100%;
  background: linear-gradient(var(--accent-color), transparent);
  border-radius: 10px;
  animation: pulseMove 3s linear infinite;
  filter: blur(5px);
}

.status-message {
  color: var(--text-color);
  font-size: 1.1rem;
  margin-top: 15px;
  text-shadow: 1px 1px 4px rgba(0, 0, 0, 0.6);
  animation: slideUp 1s ease-out;
}

.close-btn {
  padding: 10px 20px;
  font-size: 1.1rem;
  color: var(--bg-color);
  background: var(--secondary-color);
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.4s ease, transform 0.4s ease, box-shadow 0.4s ease;
}

.close-btn:hover {
  background: var(--button-hover);
  transform: scale(1.1) rotate(5deg);
  box-shadow: 0 0 15px rgba(0, 0, 0, 0.3);
}

