<template>
  <div class="details-container">
    <!-- Top-left details -->
    <div class="details-header">
      <div>
        <p><strong>Run Name:</strong> {{ runDetails.run_name }}</p>
        <p><strong>Task:</strong> {{ runDetails.task }}</p>
        <p><strong>Timestamp:</strong> {{ runDetails.timestamp }}</p>
      </div>
    </div>

    <!-- Categorical Columns -->
    <div class="section">
      <h4>Categorical Columns</h4>
      <div class="column-group" v-for="(column, index) in categoricalColumns" :key="index">
        <label :for="`cat-${column}`">{{ column }}:</label>
        <select v-model="selectedValues[column]" :id="`cat-${column}`" class="dropdown">
          <option v-for="value in uniqueValues[column]" :key="value" :value="value">
            {{ value === null ? 'N/A' : value }}
          </option>
        </select>
      </div>
    </div>

    <!-- Numerical Columns -->
    <div class="section">
      <h4>Numerical Columns</h4>
      <div class="column-group" v-for="(column, index) in numericalColumns" :key="index">
        <label :for="`num-${column}`">{{ column }}:</label>
        <input
          type="number"
          v-model.number="selectedValues[column]"
          :id="`num-${column}`"
          class="number-input"
          placeholder="Enter a number"
        />
      </div>
    </div>

    <!-- Models -->
    <div class="section" v-if="models.length > 1">
      <h4>Model Selection</h4>
      <div class="column-group">
        <label for="model-select">Model:</label>
        <select v-model="selectedModel" id="model-select" class="dropdown">
          <option v-for="model in models" :key="model" :value="model">
            {{ model }}
          </option>
        </select>
      </div>
    </div>
    <div class="section" v-else-if="models.length === 1">
      <p><strong>Model:</strong> {{ models[0] }}</p>
    </div>

    <!-- Submit Button and Result -->
    <!-- Submit Button and Result -->
<div class="submit-section">
  <button @click="submitForm" :disabled="!isFormValid" class="submit-btn">Submit</button>
  <div v-if="resultMessage" class="result" :class="{ 'success': !error, 'error': error }">
    {{ resultMessage }}
  </div>
  <div v-if="inferenceResult" class="final-result-section">
    <h4>Final Result</h4>
    <div v-if="runDetails.task === 'MLClassification'" class="result-details">
      <p><strong>Prediction:</strong> {{ inferenceResult.prediction }}</p>
      <p><strong>Probabilities:</strong> {{ inferenceResult.probabilities }}</p>
    </div>
    <div v-else-if="runDetails.task === 'MLRegression'" class="result-details">
      <p><strong>Prediction:</strong> {{ inferenceResult.prediction }}</p>
    </div>
  </div>
</div>
<div class="contact-us-container">
  <h3 class="contact-title">Contact Us</h3>

  <div class="contact-grid">

    <!-- Project Email -->
     <div class="project-row">
      <span class="label">Project Email:</span>
      <a :href="'mailto:' + contactInfo.projectEmail" class="p-email">
        {{ contactInfo.projectEmail }}
      </a>
    </div>

    <!-- MEMBERS (horizontal sleeping line) -->
    <div class="members-row">
      <div
        v-for="(member, index) in contactInfo.members"
        :key="index"
        class="member-chip"
      >
        <span class="member-name">{{ member.name }}:</span>
        <a :href="'https://mail.google.com/mail/?view=cm&fs=1&to=' + member.email" target="_blank" class="contact-email">
          {{ member.email }}
        </a>
      </div>
    </div>

  </div>
      </div>
  </div>
</template>

<script>
import { apiConfig, sanitizeAndParseResponse} from '@/config/apiConfig';
import axios from 'axios';

export default {
  name: 'RunDetails',
  data() {
    return {
      runDetails: {
        column_data: { categorical_columns: [], numerical_columns: [], unique_values: {} },
        folder_path: '',
        id: null,
        models: [],
        run_name: '',
        task: '',
        timestamp: ''
      },
      selectedValues: {},
      selectedModel: '',
      resultMessage: '',
      error: false,
      errorMessage: '',
      inferenceResult: null,
       contactInfo: {
        projectEmail: 'contact.easyml@gmail.com', 
       members: [
          {name:"Dhruv Jain",email:'djamitjn@gmail.com'}, 
          {name:"Esha Mishra",email:'emish8cool@gmail.com'}, 
          {name:"Pawan K Jain",email:'pawanjain72002@gmail.com'}, 
          {name:"Yatrik Shah",email:'yatriksshah@gmail.com'}, 
        ],
      
      
      },
    };
  },
  computed: {
    categoricalColumns() {
      return this.runDetails.column_data.categorical_columns || [];
    },
    numericalColumns() {
      return this.runDetails.column_data.numerical_columns || [];
    },
    uniqueValues() {
      return this.runDetails.column_data.unique_values || {};
    },
    models() {
      return this.runDetails.models || [];
    },
    isFormValid() {
      return this.categoricalColumns.every(col => this.selectedValues[col] !== undefined) &&
             this.numericalColumns.every(col => this.selectedValues[col] !== null && !isNaN(this.selectedValues[col]));
    }
  },
  mounted() {
    const runId = this.$route.params.id;
    if (runId) {
      this.fetchRunDetails(runId);
    }
  },
  methods: {
  async fetchRunDetails(runId) {
    try {
      console.log('Fetching run details for runId:', runId);

      const response = await axios.get(
        `${apiConfig.endpoints.showDetailsRunEndpoint()}?run_id=${runId}`,
        {
          transformResponse: [sanitizeAndParseResponse]
        }
      );

      const data = response.data;

      if (!data) {
        this.errorMessage = 'Failed to parse API response.';
        return;
      }

      this.runDetails = data;
      this.categoricalColumns.forEach(col => {
        this.selectedValues[col] = null;
      });
      this.numericalColumns.forEach(col => {
        this.selectedValues[col] = null;
      });
      this.selectedModel = this.models.length > 0 ? this.models[0] : '';
      this.errorMessage = '';
    } catch (error) {
      console.error('Error fetching run details:', error);
      this.errorMessage = 'Network or server error while fetching run details.';
    }
  },
    async submitForm() {
      this.resultMessage = 'Processing...';
      this.error = false;
      this.inferenceResult = null; // Clear previous result
      try {
        const response = await axios.post(apiConfig.endpoints.InferenceRunEndpoint(), {
          run_id: this.runDetails.id,
          model_name: this.selectedModel,
          data: this.selectedValues
        }, {
          headers: { 'Content-Type': 'application/json' },
          transformResponse: [sanitizeAndParseResponse]
        });
        this.inferenceResult = response.data;
        this.resultMessage = 'Inference completed successfully.';
      } catch (error) {
        console.error('Error submitting form:', error);
        this.inferenceResult = null;
        this.resultMessage = error.response?.data?.error_message || 'Failed to get inference result.';
        this.error = true;
      }
    }
  
  }
};
</script>

<style scoped>
