  margin: 20px 0;
  padding: 15px;
  background: var(--header-bg);
  border-radius: 5px;
  text-align: left;
}

.details-header p {
  margin: 5px 0;
}

.section {
  margin-bottom: 19px;
}

h4 {
  color: var(--primary-color);
  margin-bottom: 20px;
  border-color: #2ecc71;
  text-decoration: wavy;
  font-family: Georgia;
  /* text-transform: uppercase; */
  font-size: large;
}

.column-group {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}

label {
  font-weight: bold;
  min-width: 120px;
}

.dropdown {
  padding: 8px;
  border: 1px solid var(--border-color);
  border-radius: 5px;
  background: var(--bg-color);
  color: var(--text-color);
  width: 200px;
}

.number-input {
  padding: 8px;
  border: 1px solid var(--border-color);
  border-radius: 5px;
  background: var(--bg-color);
  color: var(--text-color);
  width: 200px;
}

.submit-section {
  text-align: center;
  margin-top: 20px;
}

.submit-btn {
  padding: 12px 25px;
  background: linear-gradient(45deg, #27ae60, #2ecc71);
  color: var(--bg-color);
  border: none;
  border-radius: 25px;
