}

/* Member name bold */
.member-name {
  padding: 0%;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-color);
}

/* email styling */
.contact-email {
  color: var(--secondary-color);
  text-decoration: none;
  font-size: 15px;
